import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import {blockCanvas,extractBlock,openBlock,placeBlock,validateBlock} from '../dist/tactics/blocks.js';
import {connectionSet,validateConnections} from '../dist/tactics/connections.js';
import {generateConnectedMap} from '../dist/tactics/block-generator.js';
import {blankMap,setTerrain,validateMap,parseMap} from '../dist/tactics/maps.js';
const rules=(north='none',east='none',south='none',west='none')=>({north,east,south,west});
function stripe(type){const m=blockCanvas(type);if(type==='road'||type==='river'){for(let y=9;y<=14;y++)for(let x=0;x<24;x++)m.terrain[y][x]=type==='road'?'ground-asphalt':'water';m.blockConnections={'0,0':rules('none',type,'none',type)};}else if(type==='cliff'){for(let y=0;y<24;y++)for(let x=11;x<24;x++)setTerrain(m,x,y,1,'floor');m.blockConnections={'0,0':rules(type,'none',type,'none')};}else{for(let y=0;y<24;y++)m.edges['e:10:'+y]=type==='fence'?'fence-chainlink':'wall-concrete';m.blockConnections={'0,0':rules(type,'none',type,'none')};}return extractBlock(m);}
test('all five connection types preserve metadata through block and map JSON',()=>{for(const type of ['fence','road','river','wall','cliff']){const d=validateBlock(stripe(type)),m=openBlock(JSON.parse(JSON.stringify(d)));assert.deepEqual(extractBlock(m).connections,d.connections);const full=placeBlock(blankMap(),d,2,2);assert.deepEqual(parseMap(JSON.stringify(full),{allowDisconnected:true}).blockConnections['2,2'],d.connections);}});
test('one element per direction rejects multiple roads and compound features',()=>{const m=openBlock(stripe('road'));m.terrain[2][0]='ground-asphalt';assert.throws(()=>connectionSet(m,0,0,rules('none','road','none','road')),/continuous/);m.terrain[2][0]='yard';m.edges['s:0:4']='fence-chainlink';assert.throws(()=>connectionSet(m,0,0,rules('none','road','none','road')),/one element/);assert.throws(()=>connectionSet(m,0,0,{north:['fence','road']}),/exactly one/);});
test('adjacent roads match exact widths and reject atomically; later painting invalidates rules',()=>{const d=stripe('road');let m=placeBlock(blankMap(),d,2,2);m=placeBlock(m,d,3,2);assert.deepEqual(validateConnections(m),[]);const wrong=structuredClone(d);wrong.terrain[9].fill('yard');const before=JSON.stringify(m);assert.throws(()=>placeBlock(m,wrong,3,2),/mismatch|six tiles/);assert.equal(JSON.stringify(m),before);m.terrain[57][72]='yard';assert.ok(validateConnections(m).length);});
test('cliffs match height and side and fences match materials',()=>{for(const type of ['cliff','fence']){const d=stripe(type),m=placeBlock(blankMap(),d,2,2),other=structuredClone(d);if(type==='cliff')other.upper=[{},other.upper[0]];else for(const k of Object.keys(other.edges))other.edges[k]='fence-railing';assert.throws(()=>placeBlock(m,other,2,3),/mismatch/);}});
test('seeded generation produces 100 matched road blocks with valid starts and deterministic output',()=>{const d=stripe('road'),a=generateConnectedMap([d],7),b=generateConnectedMap([d],7);assert.equal(Object.keys(a.blockConnections).length,100);assert.deepEqual(validateMap(a),[]);assert.deepEqual(a,b);});
test('unsatisfiable and overpopulated libraries fail without touching source blocks',()=>{const d=stripe('fence');d.guards=[{x:5,y:5,z:0,species:'pig-foreman',weapon:'pistol'}];const before=JSON.stringify(d);assert.throws(()=>generateConnectedMap([d],1),/No matching/);assert.equal(JSON.stringify(d),before);assert.throws(()=>generateConnectedMap([],1),/Save at least/);});
test('user checkpoint matches the four intended directions',()=>{const d=JSON.parse(fs.readFileSync('tests/fixtures/road-meet-chain-link-fence.json','utf8'));d.connections=rules('fence','road','fence','road');assert.equal(validateBlock(d),d);});
test('road and river openings reject barriers at the seam',()=>{for(const type of ['road','river']){const d=stripe(type);d.edges['e:23:10']='wall-concrete';assert.throws(()=>validateBlock(d),/blocked/);}});
test('flat elevation and explicit seam conflicts cannot silently match',()=>{const a=blockCanvas('A');a.blockConnections={'0,0':rules()};const d=extractBlock(a);const upper=structuredClone(d);for(let y=0;y<24;y++)for(let x=0;x<24;x++)upper.upper[0][x+','+y]='floor';assert.throws(()=>placeBlock(placeBlock(blankMap(),d,2,2),upper,3,2),/mismatch/);
 d.edges['e:23:10']='wall-concrete';const other=extractBlock(a);other.edges['e:-1:10']='fence-chainlink';assert.throws(()=>placeBlock(placeBlock(blankMap(),d,2,2),other,3,2),/materials conflict/);
 const conflicting=structuredClone(d);conflicting.edges['e:-1:10']='fence-chainlink';assert.throws(()=>generateConnectedMap([conflicting],1),/No matching/);
 const retained=placeBlock(placeBlock(blankMap(),d,2,2),extractBlock(a),3,2);assert.equal(retained.edges['e:71:58'],'wall-concrete');
});
